using Guna.UI2.WinForms;
namespace BetaFit.Desktop.Controls;
public sealed class UcSidebar:UserControl { public event EventHandler? DashboardClicked,ProductsClicked,CategoriesClicked,SettingsClicked,LogoutClicked; public UcSidebar(){Width=230;Dock=DockStyle.Left;BackColor=Color.FromArgb(20,24,31);Padding=new Padding(14);var logo=new Label{Text="BETAFIT",ForeColor=Color.White,Font=new Font("Segoe UI Semibold",18),Dock=DockStyle.Top,Height=60,TextAlign=ContentAlignment.MiddleCenter};var flow=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false};Add(flow,"Dashboard",()=>DashboardClicked?.Invoke(this,EventArgs.Empty));Add(flow,"Produtos",()=>ProductsClicked?.Invoke(this,EventArgs.Empty));Add(flow,"Categorias",()=>CategoriesClicked?.Invoke(this,EventArgs.Empty));Add(flow,"Configurações",()=>SettingsClicked?.Invoke(this,EventArgs.Empty));Add(flow,"Sair",()=>LogoutClicked?.Invoke(this,EventArgs.Empty));Controls.Add(flow);Controls.Add(logo);} private static void Add(FlowLayoutPanel f,string text,Action a){var b=new Guna2Button{Text=text,Width=200,Height=44,Margin=new Padding(0,4,0,4),BorderRadius=8,FillColor=Color.FromArgb(31,38,48),ForeColor=Color.White,Cursor=Cursors.Hand};b.Click+=(_,_)=>a();f.Controls.Add(b);} }